fn validate_control_group_with_budget<K: Ord + Borrow<PathState>>(
    function: &ResolvedFunction,
    states: &BTreeSet<K>,
    block: BlockId,
    budget: &mut ReplayBudget,
) -> Result<(), Diagnostic> {
    for state in states {
        validate_join_compatibility(
            function,
            states.range::<K, _>(..state).map(|prior| prior.borrow()),
            state.borrow(),
            block,
            budget,
        )?;
    }
    Ok(())
}

